    }

    const { lockerId, value } = validation;
    if (topic.endsWith('/availability')) {
      this.cache.ingestAvailability(lockerId, value, observedAt);
      return { accepted: true, type: 'availability' };
    }
    if (topic.endsWith('/state')) {
