  color: var(--muted);
}

.status-cell strong {
  min-width: 0;
  align-self: start;
  color: var(--text);
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  font-size: clamp(0.86rem, 1.3vw, 1rem);
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.status-cell--lock strong {
  color: var(--amber);
}

.status-meta-grid {
  display: grid;
  grid-template-columns: minmax(200px, 0.35fr) minmax(0, 0.65fr);
  gap: 10px;
  margin-top: 10px;
}

.status-meta {
  display: grid;
  min-width: 0;
  gap: 5px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: rgba(6, 17, 24, 0.56);
}

.status-meta strong {
  min-width: 0;
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  font-size: 0.78rem;
  font-weight: 650;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.status-meta--alert strong {
  color: var(--amber);
}

.message--state,
.message--command {
  position: relative;
  margin-top: 12px;
  padding: 11px 13px 11px 36px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(67, 215, 231, 0.045);
}

.message--state::before,
.message--command::before {
  position: absolute;
  top: 14px;
  left: 14px;
  width: 9px;
  height: 9px;
  border: 2px solid var(--cyan-deep);
  border-radius: 50%;
  content: "";
}

.controls {
  display: grid;
  gap: 17px;
  margin-top: 22px;
}

.control-group {
  min-width: 0;
}

.control-group-label {
  display: block;
  margin-bottom: 7px;
}

.control-buttons {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
}

.control-button {
  position: relative;
  display: grid;
  min-width: 0;
  min-height: 66px;
  justify-items: start;
  align-content: center;
  gap: 4px;
  padding: 11px 13px;
  overflow: hidden;
  border: 1px solid rgba(98, 221, 167, 0.32);
  border-radius: 11px;
  background: rgba(98, 221, 167, 0.08);
  color: #dffbec;
  cursor: pointer;
  font-weight: 730;
  text-align: left;
  transition: border-color 150ms ease, background-color 150ms ease, transform 150ms ease;
}

.control-button--open {
  border-color: var(--line-strong);
  background: transparent;
  color: var(--text);
}

.control-button:hover:not(:disabled) {
  border-color: var(--green);
  background: rgba(98, 221, 167, 0.13);
  transform: translateY(-1px);
}

.control-button .control-code {
  color: var(--green);
  font-size: 0.62rem;
}

.control-button:disabled .control-code {
  color: #78919b;
}

.control-button[data-pending="true"] {
  border-color: rgba(244, 201, 107, 0.6);
  background: rgba(244, 201, 107, 0.09);
  color: #ffe6a9;
  cursor: progress;
}

.control-button[data-pending="true"]::after {
  position: absolute;
  top: 11px;
  right: 11px;
  width: 12px;
  height: 12px;
  border: 2px solid rgba(244, 201, 107, 0.24);
  border-top-color: var(--amber);
  border-radius: 50%;
  content: "";
  animation: spin 750ms linear infinite;
}

.chat-form {
  position: relative;
  display: grid;
  gap: 10px;
  margin-top: 22px;
}

form[data-pending="true"] {
  cursor: progress;
}

form[data-pending="true"] input,
form[data-pending="true"] textarea,
form[data-pending="true"] button {
  opacity: 0.68;
  pointer-events: none;
}

form[data-pending="true"]::after {
  position: absolute;
  top: 10px;
  right: 10px;
  z-index: 2;
  width: 15px;
  height: 15px;
  border: 2px solid rgba(244, 201, 107, 0.26);
  border-top-color: var(--amber);
  border-radius: 50%;
  content: "";
  animation: spin 750ms linear infinite;
}

.chat-submit {
  justify-self: start;
}

.answer-shell {
  min-width: 0;
  margin-top: 16px;
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: rgba(4, 13, 19, 0.72);
}

#answer {
  min-width: 0;
  min-height: 80px;
  margin: 8px 0 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--muted-strong);
  font-family: inherit;
  font-size: 0.86rem;
  line-height: 1.55;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.page-footer {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 22px 4px 0;
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 0.66rem;
}

.page-footer p {
  margin: 0;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

@media (max-width: 960px) {
  .identity-grid,
  .action-grid {
    grid-template-columns: 1fr;
  }

  .status-rail {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {
  .app-shell {
    width: min(100% - 24px, 1180px);
    padding-top: 18px;
  }

  .topbar {
    display: grid;
    gap: 15px;
    padding-bottom: 17px;
  }

  .session-panel {
